  {
    size_t cnt = path.size();
    if (cnt < 3) return 0.0;
    double a = 0.0;
    typename Path<T>::const_iterator it1 = path.cend() -1, it2 = path.cbegin();
    for (; it2 != path.cend(); it1 = it2, ++it2)
      a += static_cast<double>(it1->y + it2->y) * static_cast<double>(it1->x - it2->x);
    return a * 0.5;
  }
  ```
  Note: `it1->y + it2->y` is int64 addition (could overflow in general but fine here), cast to double, times (it1->x - it2->x) int64 → double.

