void GetLowestClosedPathInfo(const Paths64& paths, std::optional<size_t>& lowest_idx, bool& is_reversed)
{
	lowest_idx.reset();
	Point64 botPt = Point64(INT64_MAX, INT64_MIN);
	for (size_t i = 0; i < paths.size(); ++i)
	{
		double a = Area(paths[i]);
		if (a == 0) continue;
		// don't need to find a lowermost vertex in open paths
		for (const Point64& pt : paths[i])
		{
			if ((pt.y < botPt.y) ||
				((pt.y == botPt.y) && (pt.x >= botPt.x))) continue;
			lowest_idx = i;
			botPt = pt;
			is_reversed = (a < 0);
		}
	}
}
