// test20 — Rust reimplementation of the C++ Clipper2 test program.
// std-only, edition 2021.

mod clipper;

use clipper::engine::{Clipper64, ClipType, FillRule};
use clipper::offset::{inflate_paths, EndType, JoinType};
use clipper::core::*;

/// Mimic std::stoi: skip leading ASCII whitespace, optional sign, digits.
/// Returns None when conversion would throw (invalid_argument / out_of_range).
fn stoi(s: &str) -> Option<i32> {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_ascii_whitespace() {
        i += 1;
    }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        neg = bytes[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val.saturating_mul(10).saturating_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    if i == start {
        return None; // invalid_argument
    }
    let val = if neg { -val } else { val };
    if val < i32::MIN as i64 || val > i32::MAX as i64 {
        return None; // out_of_range
    }
    Some(val as i32)
}

/// C++ default ostream formatting for double: %g with 6 significant digits.
fn format_g6(v: f64) -> String {
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }
    if !v.is_finite() {
        // not expected, but be safe
        return if v.is_sign_negative() { "-inf".to_string() } else { "inf".to_string() };
    }
    let neg = v < 0.0;
    let a = v.abs();
    // Round to 6 significant digits via scientific formatting.
    let sci = format!("{:.5e}", a); // e.g. "1.48927e4"
    let epos = sci.find('e').unwrap();
    let mant = &sci[..epos]; // "1.48927"
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    // digits: 6 significant digits without the dot
    let mut digits = String::new();
    for c in mant.chars() {
        if c != '.' {
            digits.push(c);
        }
    }
    debug_assert_eq!(digits.len(), 6);
    let sign = if neg { "-" } else { "" };
    if exp < -4 || exp >= 6 {
        // scientific notation: strip trailing zeros of mantissa
        let mut m: Vec<char> = digits.chars().collect();
        while m.len() > 1 && *m.last().unwrap() == '0' {
            m.pop();
        }
        let mstr: String = {
            let mut s = String::new();
            s.push(m[0]);
            if m.len() > 1 {
                s.push('.');
                for c in &m[1..] {
                    s.push(*c);
                }
            }
            s
        };
        let esign = if exp < 0 { '-' } else { '+' };
        let eabs = exp.abs();
        format!("{}{}e{}{:02}", sign, mstr, esign, eabs)
    } else if exp >= 0 {
        let ip = exp as usize + 1;
        let int_part = &digits[..ip];
        let frac = digits[ip..].trim_end_matches('0');
        if frac.is_empty() {
            format!("{}{}", sign, int_part)
        } else {
            format!("{}.{}", sign, int_part, frac)
        }
    } else {
        // -4 <= exp < 0 : 0.000ddd
        let zeros = (-exp - 1) as usize;
        let frac_full = format!("{}{}", "0".repeat(zeros), digits);
        let frac = frac_full.trim_end_matches('0');
        if frac.is_empty() {
            format!("{}0", sign)
        } else {
            format!("{}0.{}", sign, frac)
        }
    }
}

fn build_geometry_layers(complexity: i32) -> Vec<Paths64> {
    let mut geometry_layers: Vec<Paths64> = Vec::new();

    // Layer 1: circles + squares
    let mut layer1: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        let mut circle: Path64 = Vec::new();
        for j in 0..24i64 {
            let angle = 2.0f64 * 3.1415926f64 * (j as f64) / 24.0f64;
            let x = 100 + i * 80 + (40.0f64 * angle.cos()) as i64;
            let y = 100 + (40.0f64 * angle.sin()) as i64;
            circle.push(Point64::new(x, y));
        }
        layer1.push(circle);

        let mut square: Path64 = Vec::new();
        let size: i64 = 50 + i * 10;
        square.push(Point64::new(200 + i * 60, 200));
        square.push(Point64::new(200 + i * 60 + size, 200));
        square.push(Point64::new(200 + i * 60 + size, 200 + size));
        square.push(Point64::new(200 + i * 60, 200 + size));
        layer1.push(square);
    }
    geometry_layers.push(layer1);

    // Layer 2: stars + spirals
    let mut layer2: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        let mut star: Path64 = Vec::new();
        let points: i64 = 5 + i;
        for j in 0..(points * 2) {
            let angle = 2.0f64 * 3.1415926f64 * (j as f64) / ((points * 2) as f64);
            let radius = if j % 2 == 0 { 35.0f64 } else { 20.0f64 };
            let x = 150 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            star.push(Point64::new(x, y));
        }
        layer2.push(star);

        let mut spiral: Path64 = Vec::new();
        for j in 0..30i64 {
            let t = (j as f64) * 0.3f64;
            let radius = 10.0f64 + t * 4.0f64;
            let angle = t;
            let x = 300 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            spiral.push(Point64::new(x, y));
        }
        layer2.push(spiral);
    }
    geometry_layers.push(layer2);

    // Layer 3: hexagon grid + triangles
    let mut layer3: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        for j in 0..complexity as i64 {
            let mut hex: Path64 = Vec::new();
            let center_x: i64 = 50 + i * 70;
            let center_y: i64 = 300 + j * 70;
            for k in 0..6i64 {
                let angle = 2.0f64 * 3.1415926f64 * (k as f64) / 6.0f64;
                let x = center_x + (25.0f64 * angle.cos()) as i64;
                let y = center_y + (25.0f64 * angle.sin()) as i64;
                hex.push(Point64::new(x, y));
            }
            layer3.push(hex);

            let mut triangle: Path64 = Vec::new();
            triangle.push(Point64::new(center_x + 100, center_y));
            triangle.push(Point64::new(center_x + 100 + 30, center_y + 50));
            triangle.push(Point64::new(center_x + 100 - 30, center_y + 50));
            layer3.push(triangle);
        }
    }
    geometry_layers.push(layer3);

    geometry_layers
}

fn boolean_op(ct: ClipType, subject: &Paths64, clip: &Paths64, fr: FillRule) -> Paths64 {
    let mut c = Clipper64::new();
    c.add_subject(subject.clone());
    if !clip.is_empty() {
        c.add_clip(clip.clone());
    }
    let mut sol = Paths64::new();
    c.execute(ct, fr, &mut sol);
    sol
}

fn union(paths: &Paths64, fr: FillRule) -> Paths64 {
    boolean_op(ClipType::Union, paths, &Paths64::new(), fr)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let complexity: i32 = if args.len() > 1 {
        match stoi(&args[1]) {
            Some(v) => std::cmp::min(v, 5),
