void AddPaths_(const Paths64& paths, PathType polytype, bool is_open,
	std::vector<Vertex*>& vertexLists, std::vector<std::unique_ptr<LocalMinima>>& locMinList)
{
	const auto total_vertex_count = std::accumulate(paths.begin(), paths.end(), size_t(0),
		[](const auto& a, const Path64& path) { return a + path.size(); });
	if (total_vertex_count == 0) return;

	Vertex* vertices = new Vertex[total_vertex_count];
	Vertex* v = vertices;
	for (const Path64& path : paths)
	{
		Vertex* v0 = v, *curr_v = v, *prev_v = nullptr;
		if (path.empty()) continue;
		v->prev = nullptr;
		int i = 0;
		for (const Point64& pt : path)
		{
			if (prev_v && prev_v->pt == pt) continue;
			if (prev_v) prev_v->next = curr_v;
			curr_v->prev = prev_v;
			curr_v->pt = pt;
			curr_v->flags = VertexFlags::None;
			prev_v = curr_v++;
			++i;
		}
		if (!prev_v || !prev_v->next) continue;   // single vertex path (also covers i==0)
		if (!is_open && v0->pt == prev_v->pt)
			prev_v = prev_v->prev;
		prev_v->next = v0;
		v0->prev = prev_v;
		v = curr_v;
		if (i < 2) continue;         // i <= 1
		if (i == 2 && !is_open) continue;
		bool going_up, going_up0;
		if (is_open)
		{
			curr_v = v0->next;
			while (curr_v != v0 && curr_v->pt.y == v0->pt.y) curr_v = curr_v->next;
			going_up = curr_v->pt.y <= v0->pt.y;
			if (going_up)
			{
				v0->flags = VertexFlags::OpenStart;
				AddLocMin(locMinList, *v0, polytype, true);
			}
			else
				v0->flags = VertexFlags::OpenStart | VertexFlags::LocalMax;
		}
		else
		{
			prev_v = v0->prev;
			while (prev_v != v0 && prev_v->pt.y == v0->pt.y) prev_v = prev_v->prev;
			if (prev_v == v0) continue;  // only open paths can be completely flat
			going_up = prev_v->pt.y > v0->pt.y;
		}
		going_up0 = going_up;
		prev_v = v0;
		curr_v = v0->next;
		while (curr_v != v0)
		{
			if (curr_v->pt.y > prev_v->pt.y && going_up)
			{
				prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
				going_up = false;
			}
			else if (curr_v->pt.y < prev_v->pt.y && !going_up)
			{
				going_up = true;
				AddLocMin(locMinList, *prev_v, polytype, is_open);
			}
			prev_v = curr_v;
			curr_v = curr_v->next;
		}
		if (is_open)
		{
			prev_v->flags = prev_v->flags | VertexFlags::OpenEnd;
			if (going_up)
				AddLocMin(locMinList, *prev_v, polytype, is_open);  // 40dd01
			else
				prev_v->flags = prev_v->flags | VertexFlags::LocalMax; // 40dce3
		}
		else if (going_up != going_up0)  // 40dd23: al=going_up; cmp going_up0; je continue
		{
			if (going_up0)  // 40dd2c: je 40dd52 if going_up0==0
				AddLocMin(locMinList, *prev_v, polytype, false);
			else
				prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
		}
	}
	vertexLists.push_back(vertices);
