void ClipperBase::SetWindCountForClosedPathEdge(Active& e)
{
	//Wind counts refer to polygon regions not edges, so here an edge's WindCnt
	//indicates the higher of the wind counts for the two regions touching the edge.
	//(NB: Adjacent region wind counts can only ever differ by one.)
	//Note that if all wind counts are the same (ie just subject polygons) then
	//WindCnt2 is superfluous (but it's still needed when there are also clip polygons).

	Active* e2 = e.prev_in_ael;
	//find the nearest closed path edge of the same PolyType in AEL (heading left)
	PathType pt = GetPolyType(e);
	while (e2 && (GetPolyType(*e2) != pt || IsOpen(*e2))) e2 = e2->prev_in_ael;

	if (!e2)
	{
		e.wind_count = e.wind_dx;
		e2 = actives_;
	}
	else if (fillrule_ == FillRule::EvenOdd)
	{
		e.wind_count = e.wind_dx;
		e.wind_count2 = e2->wind_count2;
	}
	else if (e2->wind_count * e2->wind_dx < 0)
	{
		//the current edge is inside the previous edge's 'interior' region
		if (std::abs(e2->wind_count) > 1)
		{
			//we're outside the prev edge's interior region, so the current edge
			//is inside the next interior region (and so on) ...
			if (e2->wind_dx * e.wind_dx < 0)
				e.wind_count = e2->wind_count;
			else
				e.wind_count = e2->wind_count + e.wind_dx;
		}
		else
			//the previous edge is the boundary of the first interior region
			//and since wind_dx and wind_count always have the same sign (in the
			//same region), the current edge must be in the second interior region
			e.wind_count = (e2->wind_dx * e.wind_dx < 0) ?
				e2->wind_count + e2->wind_dx : e2->wind_count + e.wind_dx;
	}
	else
	{
		e.wind_count = e2->wind_count + e.wind_dx;
	}
	e.wind_count2 = e2->wind_count2;

	//count the number of times the edge crosses an edge of the opposite PolyType
	e2 = e.next_in_ael;
	while (e2)
	{
		if (GetPolyType(*e2) != pt && !IsOpen(*e2))
		{
			if (fillrule_ == FillRule::EvenOdd)
				e.wind_count2 = (e.wind_count2 == 0) ? 1 : 0;
			else
				e.wind_count2 += e2->wind_dx;
		}
		e2 = e2->next_in_ael;
	}
}
