bool ClipperBase::IsContributingClosed(const Active& e) const
{
	FillRule fill_rule = fillrule_;
	switch (fill_rule)
	{
	case FillRule::EvenOdd: break;
	case FillRule::NonZero: if (std::abs(e.wind_count) != 1) return false; break;
	case FillRule::Positive: if (e.wind_count != 1) return false; break;
	case FillRule::Negative: if (e.wind_count != -1) return false; break;
	}

	switch (cliptype_)
	{
	case ClipType::Intersection:
		switch (fill_rule)
		{
		case FillRule::EvenOdd: return (e.wind_count2 != 0);
		case FillRule::NonZero: return (e.wind_count2 != 0);
		case FillRule::Positive: return (e.wind_count2 > 0);
		case FillRule::Negative: return (e.wind_count2 < 0);
		}
		break;
	case ClipType::Union:
		switch (fill_rule)
		{
		case FillRule::EvenOdd: return (e.wind_count2 == 0);
		case FillRule::NonZero: return (e.wind_count2 == 0);
		case FillRule::Positive: return (e.wind_count2 <= 0);
		case FillRule::Negative: return (e.wind_count2 >= 0);
		}
		break;
	case ClipType::Difference:
		bool result;
		switch (fill_rule)
		{
		case FillRule::EvenOdd: result = (e.wind_count2 == 0); break;
		case FillRule::NonZero: result = (e.wind_count2 == 0); break;
		case FillRule::Positive: result = (e.wind_count2 <= 0); break;
		case FillRule::Negative: result = (e.wind_count2 >= 0); break;
		}
		if (GetPolyType(e) == PathType::Subject)
			return result;
		else
			return !result;
		break;
	case ClipType::Xor: return true; break;
	}
	return false; // we should never get here
}
