bool IsContributingClosed(const Active& e) const
{
	switch (fillrule_)  // [this+0xc]: 0=EvenOdd: break; 1=NonZero: if (abs(e.wind_count) != 1) return false; 2=Positive: if (e.wind_count != 1) return false; 3=Negative: if (e.wind_count != -1) return false;
	...

	switch (cliptype_)  // [this+0x8], jump table: 0=None→0x40e763(return 0), 1=Intersection→0x40e76d, 2=Union→0x40e7b1, 3=Difference→0x40e7f4, 4=Xor→0x40e85c(return 1)
	{
	case Intersection:
		switch (fillrule_) {
		case Positive: return e.wind_count2 > 0;
		case Negative: return e.wind_count2 < 0;   // shr 31
		default: return e.wind_count2 != 0;   // EvenOdd/NonZero
		}
	case Union:
		switch (fillrule_) {
		case Positive: return e.wind_count2 <= 0;
		case Negative: return e.wind_count2 >= 0;  // not; shr 31 → ~x >>> 31 → x >= 0
		default: return e.wind_count2 == 0;
		}
	case Difference:
		bool result;
		switch (fillrule_) {
		case Positive: result = e.wind_count2 <= 0; break;
		case Negative: result = e.wind_count2 >= 0; break;
		default: result = e.wind_count2 == 0; break;
		}
		if (GetPolyType(e) == Subject) return result; else return !result;
	case Xor: return true;
	}
	return false;
}
```

